package com.configmonitor.app;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class AlarmRecoveryTest {
 JSONObject incident()throws Exception {JSONObject n=Parser.j("id",1,"enabled",true,"lastCheck",1000);for(int i=0;i<6;i++)Rules.apply(n,false,-1,1000,6);return n;}
 @Test public void committedIncidentWithLostDeliveryIsRecovered()throws Exception {JSONObject n=incident();assertTrue(n.getBoolean("alerted"));assertTrue(AlarmRecovery.missing(n,false,1001));assertFalse(AlarmRecovery.missing(n,true,1001));}
 @Test public void firstRedCardDoesNotBypassFailureThreshold()throws Exception {JSONObject n=Parser.j("enabled",true);for(int i=1;i<6;i++){Rules.apply(n,false,-1,i,6);assertFalse(AlarmRecovery.missing(n,false,100));}Rules.apply(n,false,-1,6,6);assertTrue(AlarmRecovery.missing(n,false,100));}
 @Test public void acknowledgementAndDisableDoNotRearm()throws Exception {JSONObject n=incident().put("ack",true);assertFalse(AlarmRecovery.missing(n,false,1001));n.put("ack",false).put("enabled",false);assertFalse(AlarmRecovery.missing(n,false,1001));}
 @Test public void recoveryDoesNotRestoreOldIncident()throws Exception {JSONObject n=incident();Rules.apply(n,true,80,1100,6);assertFalse(AlarmRecovery.missing(n,false,1101));for(int i=0;i<6;i++)Rules.apply(n,false,-1,1200+i,6);assertTrue(AlarmRecovery.missing(n,false,1300));}
 @Test public void suppressionNeedsFreshCheckAfterExpiry()throws Exception {for(String key:new String[]{"snoozeUntil","maintenanceUntil"}){JSONObject n=incident().put(key,2000);assertFalse(AlarmRecovery.missing(n,false,1500));assertFalse(AlarmRecovery.missing(n,false,2100));n.put("lastCheck",2100);assertTrue(AlarmRecovery.missing(n,false,2101));}}
 @Test public void audioRetryIsBoundedAndStopsAfterAck(){assertTrue(AlarmRecovery.retryAudio(true,false,5000,0));assertFalse(AlarmRecovery.retryAudio(true,false,4999,0));assertFalse(AlarmRecovery.retryAudio(true,true,6000,0));assertFalse(AlarmRecovery.retryAudio(false,false,6000,0));}
 @Test public void notificationFailureCannotSuppressSoundOrVibration(){List<String> calls=new ArrayList<>();int mask=AlarmDelivery.run(()->{throw new SecurityException("notifications denied");},()->calls.add("sound"),()->calls.add("vibration"));assertEquals(1,mask);assertEquals(Arrays.asList("sound","vibration"),calls);}
 @Test public void audioFailureCannotSuppressOtherAlarmEffects(){List<String> calls=new ArrayList<>();int mask=AlarmDelivery.run(()->{throw new IllegalStateException("player failed");},()->calls.add("vibration"),()->calls.add("notification"),()->calls.add("screen"));assertEquals(1,mask);assertEquals(Arrays.asList("vibration","notification","screen"),calls);}
}
